  ('Cadena Hotelera', 'CH', NULL, 'privado', 19),
  ('Entidad Financiera', 'EF', NULL, 'privado', 20)
) AS v(nombre, sigla, logo, sector, orden)
WHERE NOT EXISTS (SELECT 1 FROM "Cliente" x WHERE x."marcaId" = m.id AND x.nombre = v.nombre);
